<script setup>
import {computed} from 'vue'

import HelpTip from '../shared/components/HelpTip.vue'
import {caseReferences} from './collectionModel.js'
const props=defineProps({bindings:{type:Array,required:true},cases:{type:Array,required:true},disabled:Boolean})
const reference=name=>'{{case.'+name+'}}'
const targets=computed(()=>props.cases.filter(c=>c?.name).map(c=>({value:c.id,label:'TC-'+c.id+' · '+c.name})))
const sources=b=>props.cases.slice(0,Math.max(0,props.cases.findIndex(c=>c?.id===b.target_case_id))).filter(c=>c?.name).map(c=>({value:c.id,label:'TC-'+c.id+' · '+c.name}))
const source=b=>props.cases.find(c=>c?.id===b.source_case_id)
const variables=b=>source(b)?.steps.flatMap(s=>s.extractions||[]).map(e=>({value:e.name,label:e.name}))||[]
const rows=b=>source(b)?.data_rows?.map(r=>({value:r.name,label:r.name}))||[]
const missing=computed(()=>props.cases.filter(Boolean).flatMap(c=>caseReferences(c).filter(name=>!props.bindings.some(b=>b.target_case_id===c.id&&b.name===name)).map(name=>({target_case_id:c.id,name,source_case_id:null,source_name:'',source_row:''}))))
function add(){props.bindings.push(missing.value[0]||{target_case_id:props.cases[1]?.id||null,name:'',source_case_id:props.cases[0]?.id||null,source_name:'',source_row:''})}

import OptionPicker from '../shared/components/OptionPicker.vue'

import {copyText} from '../shared/clipboard.js'


import {Button,Empty,EmptyContent,EmptyDescription,EmptyHeader,Input,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../shared/shadcn-ui.js'
</script>
<template><section><div class="binding-tools"><Button @click="add" variant="outline" size="default" type="button" :disabled="(disabled||bindings.length>=40||cases.length<2)">添加变量关联</Button><HelpTip text="先在来源用例的响应提取中声明变量，再在目标用例中用 {{case.order_id}} 引用。只有来源用例全部成功才会传递；多数据组必须明确选择来源组。变量仅在本次测试集运行内有效。"/><span v-if="missing.length" class="min-w-0 break-words">{{missing.length}} 个用例变量尚未关联</span></div><div class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:1050}).y?({x:1050}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:1050}).x||({x:1050}).minWidth||1050)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(220)+'px'}">目标用例</TableHead><TableHead :style="{width:(180)+'px'}">目标变量名</TableHead><TableHead :style="{width:(220)+'px'}">来源用例</TableHead><TableHead :style="{width:(170)+'px'}">提取变量</TableHead><TableHead :style="{width:(180)+'px'}">来源数据组</TableHead><TableHead :style="{width:(80)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (bindings||[])" :key="typeof ('id')==='function'?('id')(record):record['id']??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><OptionPicker v-model="record.target_case_id" :disabled="disabled" aria-label="关联目标用例" @change="record.source_case_id=null;record.source_name='';record.source_row=''" class="min-w-36" :options="targets"/></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Input v-model="record.name" :disabled="disabled" placeholder="order_id" aria-label="用例变量名"/><span v-if="record.name" class="min-w-0 break-words"><code>{{reference(record.name)}}</code><Button variant="ghost" size="xs" aria-label="复制内容" @click="copyText(Array.from($event.currentTarget.parentElement.childNodes).filter(node=>node!==$event.currentTarget).map(node=>node.textContent).join(''))">复制</Button></span></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><OptionPicker v-model="record.source_case_id" :disabled="disabled" aria-label="变量来源用例" @change="record.source_name='';record.source_row=''" class="min-w-36" :options="sources(record)"/></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><OptionPicker v-model="record.source_name" :disabled="disabled" placeholder="先配置来源提取" aria-label="来源提取变量" class="min-w-36" :options="variables(record)"/></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><OptionPicker v-if="rows(record).length>1" v-model="record.source_row" :disabled="disabled" placeholder="请选择来源数据组" aria-label="来源数据组" class="min-w-36" :options="rows(record)"/><span v-else>{{rows(record)[0]?.label||'默认数据'}}</span></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{rowIndex} in [{record,rowIndex}]"><Button @click="bindings.splice(rowIndex,1)" variant="ghost" size="default" type="button" :disabled="(disabled)">移除</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(bindings||[]).length"><TableCell :colspan="6"><Empty><EmptyHeader><EmptyDescription>{{"各用例默认独立；需要衔接业务流程时添加变量关联"}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></section></template>
<style scoped>.binding-tools{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px}</style>
